fn set_at(a: &mut Vec<i32>, i: usize, val: i32) {
    // Basic bounds check to avoid panics in release mode
    if i >= a.len() {
        panic!(
            "set_at: index out of bounds (i = {}, len = {})",
            i,
            a.len()
        );
    }
    a[i] = val;
}

fn myfun(a: &mut Vec<i32>, sum: &mut Vec<i32>, N: i32) {
    // Preconditions (can be omitted if callers are trusted to satisfy them)
    assert!(N > 0 && N < 1000, "N must be in the range 1..999");
    let n_usize = N as usize;
    assert!(
        a.len() == n_usize,
        "Length of `a` must equal N (a.len() = {}, N = {})",
        a.len(),
        N
    );
    assert!(
        sum.len() == 1,
        "Length of `sum` must remain exactly 1 (sum.len() = {})",
        sum.len()
    );

    // Overwrite each element of `a` with N + 1
    let new_val = N + 1;
    for idx in 0..n_usize {
        set_at(a, idx, new_val);
    }

    // `sum` is not modified, its length remains 1
}

